import time

from taf.rfrl.procedures.resources.python.logger import \
    log_result, log_step, log_input_and_output
from taf.rfrl.procedures.resources.python.test_models.exceptions import \
    TestModuleStartingFailure, IncorrectTestModelParameter


@log_input_and_output
def wait_for_test_model_results(interval, measures=30):
    """
    Wait for test module to gather results.
    :param interval: reporting time interval set in test module page [in seconds]
    :type interval: int/str
    :param measures: number of measures to be performed.
    :type measures: int/str
    :raises ValueError if interval or measures parameter are not a number.
    """
    try:
        duration = int(interval) * int(measures)
        log_step("Sleep set to {0} seconds".format(duration))
        time.sleep(duration)

    except ValueError:
        raise IncorrectTestModelParameter("Interval and measure parameter should be a number, "
                                          "instead {0}:{1}, {2}:{3} was provided".format(interval, type(interval),
                                                                                         measures, type(measures)))


@log_input_and_output
def check_test_model_starting_status(status, response, operation):
    """
    Checks if test has started correctly or start request has
    been processed in proper way (it means that BTS does not reject
    request for test starting, e.g. "start test failed" pop-up appeared or
    start test module command run without problems). Both status and response is
    being generated by robot's "run keyword and ignore error" keyword.

    :param status: status of request to run test module - PASS/FAIL.
    :type status: str
    :response: exception thrown by method or 'None' if everything goes right
    :type response: str
    :param operation: Operation we want to serve. There are two options:
    'start_test' or 'wait_for_test'. Might be provided uppercase.
    :type operation: str
    :return: True if test module starting status is PASS
    :rtype: Boolean
    :raises TestModuleStartingFailure if there will be timeout in test start
    """
    if str(status) == "FAIL":
        msg = _get_exception_msg(operation)
        log_result(response)
        raise TestModuleStartingFailure(msg)

    return True


@log_input_and_output
def create_test_models_list(test_model):
    """
    Creates proper test models list. If function gets test model argument as string type, then returns one-element list.
    If function gets test model argument as list type, then returns the same list without any changes.
    :param test_model: Test model type
    :type test_model: unicode/string or list
    :return: List of given test models
    :rtype: list
    """
    if not isinstance(test_model, list):
        return [test_model]
    return test_model


@log_input_and_output
def prepare_beam_id_parameter(beam_id):
    """
    Prepares proper beam_id parameter list. If function gets beam_id argument as int type, then returns one-element
    list. If function gets beam_id argument as list type, then returns the same list without any changes.
    :param beam_id: beam_id parameters required to start tests conformance
    :type beam_id: int or list
    :return: List of beam_id parameter(s)
    :rtype: list
    """
    return [beam_id] if not isinstance(beam_id, list) else beam_id


@log_input_and_output
def selenium_get_cell_carrier_frequency(webui, cell_id=0, downlink=True):
    """
    Gets cell carrier frequency value for specific cell
    :param webui: webui instance
    :type webui: webui object
    :param cell_id: if of cell
    :type cell_id: int
    :param downlink: states if user looks for carrier frequency needed for downlink tests
    :type downlink: bool
    :return: carrier frequency with unit
    :rtype: str
    """
    cell_status = webui.get_cell_info(cell_id=cell_id)
    carrier_freq = _get_carrier_freq_per_cell_technology(cell_status=cell_status, downlink=downlink)
    return carrier_freq


@log_input_and_output
def get_prach_frc_index(prach_config_index):
    if prach_config_index:
        return "PRACH CI {}".format(prach_config_index)
    return "PRACH CI 0"


@log_input_and_output
def create_test_results_table(cell_id, nrarfcn_ul, rep_time_interval, ul_slots):
    """
    Creates performance test results
    :param cell_id: id of the current cell
    :type cell_id: str or int
    :param nrarfcn_ul: UL NR-ARFCN of tested cell
    :type nrarfcn_ul: str or int or None
    :param rep_time_interval: time intervals between each result in performance test
    :type rep_time_interval: str or int
    :param ul_slots: uplink slots
    :type ul_slots: str or int
    :return: dict of formatted test results table parameters
    :rtype: dict
    """

    return {
        'Local cell name': [f'NRCELL-{cell_id}'],
        'Carrier frequency': [f'{_calculate_carrier_frequency_for_nrcell(nrarfcn_ul)} MHz'],
        'Reporting time interval': [f'{rep_time_interval} '
                                    f'second{"" if int(rep_time_interval)==1 else "s"}'],
        'ul_slots': ul_slots
    }


@log_input_and_output
def _get_carrier_freq_per_cell_technology(cell_status, downlink=True):
    """
    Gets proper carrier frequency from cell_status read by webui.get_cell_info keyword as keys in such
    created dict may differ due to FDD/TDD cell technology.

    :param cell_status: Cell status read via selenium keyword mentioned above
    :type cell_status: dict
    :param downlink: States if user looks for carrier frequency needed for downlink tests (True at default).
    :type downlink: bool
    :return: Carrier frequency with unit (the same as seen on WebUI) e.g. '875.5 MHz'
    :rtype: str
    """
    try:
        log_step("Read carrier frequency from cell status assuming TDD cell technology")

        carrier_frequency = cell_status['Carrier frequency']
        log_result("Read carrier frequency: {0}".format(carrier_frequency))

        return carrier_frequency

    except KeyError:
        if downlink:
            carrier_frequency = cell_status['Downlink carrier frequency']
        else:
            carrier_frequency = cell_status['Uplink carrier frequency']

        log_result("Read carrier frequency: {0}".format(carrier_frequency))

        return carrier_frequency


@log_input_and_output
def _calculate_carrier_frequency_for_nrcell(nrarfcn):
    """
    Calculates carrier frequency using nrarfcn value. Calculator based on:
    https://www.etsi.org/deliver/etsi_ts/138100_138199/138104/16.04.00_60/ts_138104v160400p.pdf Chapter 5.4.2.1
    :param nrarfcn: NR-ARFCN
    :type nrarfcn: str or int
    :return: carrier frequency in MHz
    :rtype: float
    """
    if 0 <= int(nrarfcn) <= 599999:
        f_glob, f_ref_offs, n_ref_offs = 5, 0, 0
    elif 600000 <= int(nrarfcn) <= 2016666:
        f_glob, f_ref_offs, n_ref_offs = 15, 3000, 600000
    else:
        f_glob, f_ref_offs, n_ref_offs = 60, 24250.08, 2016667

    return f_ref_offs + f_glob * (int(nrarfcn) - n_ref_offs) * 10 ** -3


@log_input_and_output
def _get_exception_msg(operation):
    """
    Chooses between valid exception messages for operation allowed in specification and returns it.

    :param operation: Operation we want to serve. There are two options:
    'start_test' or 'wait_for_test'. Might be provided uppercase.
    :type operation: str
    :raises ValueError exception if user provides operation that is not supported.
    :return Exception message content.
    :rtype str
    """
    operation = str(operation).lower().strip()

    if operation not in ['start_test', 'wait_for_test']:
        raise ValueError("Provided operation parameter is not valid. "
                         " You can choose only between 'start_test' or 'wait_for_msg'.")

    start_msg = 'Test module start request could not been proccesed. Are You sure that' \
                ' You have requested for test module startup that is available for your' \
                ' testline configuration?'

    wait_for_start_msg = 'Test module start request was sent to BTS but it was rejected.' \
                         ' Please check screenshot that has been made due to this error in' \
                         ' your logs path to find out more about occuring situation.'

    msg = start_msg if operation == 'start_test' else wait_for_start_msg
    return msg
